using Godot;
using System.Collections.Generic;

/// <summary>
/// Per-line playback gain for voice recordings, so lines from the same player play at about the
/// same loudness without re-encoding the files (tests, transcripts and the owner's listening
/// sign-off record their hashes). The table <c>res://assets/audio/voice_gain.json</c> is generated by
/// <c>tools/assets/voice_gain.py</c>; voice players add <see cref="GainDb"/> to their own volume
/// and play on <see cref="Bus"/>, whose hard limiter catches peaks that a boost pushes over -1 dB.
/// The table caps each boost so the limiter removes at most 2 dB of peak on any line.
/// A missing table or an unlisted path gives 0 dB, so playback never depends on this file.
/// </summary>
public static class VoiceGain
{
    /// <summary>Path of the generated gain table.</summary>
    public const string TablePath = "res://assets/audio/voice_gain.json";
    /// <summary>
    /// Bus voices play on. It sends into SFX, which sends to Master, so the menu volume slider
    /// (Master, bus 0) still controls voices; no SFX-specific setting exists today.
    /// </summary>
    public const string VoiceBus = "Voice";
    /// <summary>Upper bound on any voice gain; same value as MAX_GAIN_DB in voice_gain.py and the clamp in deployment_cutscene.gd.</summary>
    public const float MaxGainDb = 12f;

    private static readonly GainTable Table = new(TablePath, MaxGainDb);

    /// <summary>Parses voice table JSON (see <see cref="GainTable.Parse"/>) with the voice gain limit.</summary>
    public static Dictionary<string, float> Parse(string json) => GainTable.Parse(json, MaxGainDb);

    /// <summary>
    /// Gain in dB for a voice resource path, or 0 when the table or the entry is absent. Without the
    /// limited Voice bus only cuts are applied, because a boost could then push peaks past full scale.
    /// </summary>
    public static float GainDb(string resPath)
    {
        float gain = Table.GainDb(resPath);
        return gain > 0 && AudioServer.GetBusIndex(VoiceBus) < 0 ? 0f : gain;
    }

    /// <summary>
    /// The Voice bus when the project's bus layout has it, otherwise SFX, so a player never
    /// routes to a missing bus (Godot would silently fall back to Master).
    /// </summary>
    public static string Bus => AudioServer.GetBusIndex(VoiceBus) >= 0 ? VoiceBus : "SFX";
}
